package net.officefloor.hq.app.person;

import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.Table;
import java.math.BigDecimal;
import java.time.LocalDate;

/** A statement taken of a person: the sheet's today then, their due-total then (none when it was n/a)
 *  and how many of their claims counted. */
@Entity
@Table(name = "statement")
public class Statement {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(name = "sheet_id", nullable = false)
    private String sheetId;

    @Column(name = "person_id", nullable = false)
    private Long personId;

    @Column(name = "taken_on", nullable = false)
    private LocalDate takenOn;

    @Column(name = "due_total")
    private BigDecimal dueTotal;

    @Column(name = "claim_count", nullable = false)
    private int claimCount;

    protected Statement() {
    }

    public Statement(String sheetId, Long personId, LocalDate takenOn, BigDecimal dueTotal, int claimCount) {
        this.sheetId = sheetId;
        this.personId = personId;
        this.takenOn = takenOn;
        this.dueTotal = dueTotal;
        this.claimCount = claimCount;
    }

    public Long getId() {
        return id;
    }

    public String getSheetId() {
        return sheetId;
    }

    public Long getPersonId() {
        return personId;
    }

    public LocalDate getTakenOn() {
        return takenOn;
    }

    public BigDecimal getDueTotal() {
        return dueTotal;
    }

    public int getClaimCount() {
        return claimCount;
    }
}
package net.officefloor.hq.app.person;

import java.util.List;
import org.springframework.data.jpa.repository.JpaRepository;

public interface StatementRepository extends JpaRepository<Statement, Long> {

    /** The sheet's statements in the order they were taken. */
    List<Statement> findBySheetIdOrderByIdAsc(String sheetId);

    /** The person's statements in the order they were taken. */
    List<Statement> findByPersonIdOrderByIdAsc(Long personId);
}
package net.officefloor.hq.app.person;

import java.time.LocalDate;
import java.util.List;
import java.util.Map;
import java.util.Objects;
import java.util.Set;
import java.util.stream.Collectors;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.rollup.Rollup;
import net.officefloor.hq.app.sheet.SheetNotFoundException;
import net.officefloor.hq.app.sheet.SheetRepository;
import org.springframework.dao.DataIntegrityViolationException;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

/**
 * Keeps the people on each sheet. Names arrive validated (not blank) and are stored trimmed; a name
 * is unique on the sheet, compared without regard to case.
 */
@Service
public class PersonService {

    private final PersonRepository people;
    private final SheetRepository sheets;
    private final StatementRepository statements;
    private final PatronRepository patrons;
    private final WatchRepository watches;
    private final Rollup rollup;
    private final Audit audit;

    public PersonService(PersonRepository people, SheetRepository sheets, StatementRepository statements,
            PatronRepository patrons, WatchRepository watches, Rollup rollup, Audit audit) {
        this.watches = watches;
        this.patrons = patrons;
        this.rollup = rollup;
        this.people = people;
        this.sheets = sheets;
        this.statements = statements;
        this.audit = audit;
    }

    @Transactional(readOnly = true)
    public List<Person> list(String sheetId) {
        requireSheet(sheetId);
        return people.findBySheetIdOrderByIdAsc(sheetId);
    }

    /** The sheet's statements by person id, each person's in the order they were taken. */
    @Transactional(readOnly = true)
    public Map<Long, List<Statement>> statements(String sheetId) {
        return statements.findBySheetIdOrderByIdAsc(sheetId).stream()
                .collect(Collectors.groupingBy(Statement::getPersonId));
    }

    /** The person's statements in the order they were taken. */
    @Transactional(readOnly = true)
    public List<Statement> statementsOf(long personId) {
        return statements.findByPersonIdOrderByIdAsc(personId);
    }

    /** The sheet's patrons: each person's patrons' ids, by person id. */
    @Transactional(readOnly = true)
    public Map<Long, List<Long>> patrons(String sheetId) {
        return patrons.findBySheetId(sheetId).stream().collect(Collectors.groupingBy(Patron::getPersonId,
                Collectors.mapping(Patron::getPatronId, Collectors.toList())));
    }

    /** The ids of the person's patrons. */
    @Transactional(readOnly = true)
    public List<Long> patronsOf(long personId) {
        return patrons.findByPersonId(personId).stream().map(Patron::getPatronId).toList();
    }

    /** Name another person on the sheet as the person's patron: not themselves, and not twice. */
    @Transactional
    public Person addPatron(String sheetId, String user, long personId, long patronId) {
        Person person = people.findByIdAndSheetId(personId, sheetId).orElseThrow(PersonNotFoundException::new);
        Person patron = people.findByIdAndSheetId(patronId, sheetId).orElseThrow(PersonNotFoundException::new);
        if (person.getId().equals(patron.getId())) {
            throw new PatronRefusedException("A person cannot be their own patron.");
        }
        if (patrons.existsByPersonIdAndPatronId(person.getId(), patron.getId())) {
            throw new PatronRefusedException(patron.getName() + " is already a patron of " + person.getName() + ".");
        }
        try {
            patrons.saveAndFlush(new Patron(sheetId, person.getId(), patron.getId()));
        } catch (DataIntegrityViolationException e) {
            // named by another user at the same moment
            throw new PatronRefusedException(patron.getName() + " is already a patron of " + person.getName() + ".");
        }
        audit.recordOnCommit("PATRON_ADDED sheet=" + sheetId + " by=" + user + " name=" + person.getName()
                + " patron=" + patron.getName());
        return person;
    }

    /** The ids of the people on the sheet the user watches. */
    @Transactional(readOnly = true)
    public Set<Long> watchedBy(String sheetId, String user) {
        return watches.findBySheetIdAndUser(sheetId, user).stream().map(Watch::getPersonId)
                .collect(Collectors.toSet());
    }

    /** Whether the user watches the person. */
    @Transactional(readOnly = true)
    public boolean watching(long personId, String user) {
        return watches.findByPersonIdAndUser(personId, user).isPresent();
    }

    /** The users watching the person, in the order they started watching. */
    @Transactional(readOnly = true)
    public List<String> watchers(long personId) {
        return watches.findByPersonIdOrderByIdAsc(personId).stream().map(Watch::getUser).toList();
    }

    /** Start (on) or stop watching a person as the user; asking for the state already held records nothing. */
    @Transactional
    public Person watch(String sheetId, String user, long personId, boolean on) {
        Person person = people.findByIdAndSheetId(personId, sheetId).orElseThrow(PersonNotFoundException::new);
        var held = watches.findByPersonIdAndUser(person.getId(), user);
        if (on == held.isPresent()) {
            return person;
        }
        if (on) {
            try {
                watches.saveAndFlush(new Watch(sheetId, person.getId(), user));
            } catch (DataIntegrityViolationException e) {
                // started at the same moment in another window
                throw new WatchRefusedException("You already watch " + person.getName() + ".");
            }
        } else {
            watches.delete(held.get());
        }
        audit.recordOnCommit((on ? "PERSON_WATCHED" : "PERSON_UNWATCHED") + " sheet=" + sheetId + " by=" + user
                + " name=" + person.getName());
        return person;
    }

    @Transactional
    public Person add(String sheetId, String user, String name, String grade, Integer terms) {
        requireSheet(sheetId);
        requireFreeName(sheetId, name.trim(), null);
        Rollup.Snapshot before = rollup.take(sheetId);
        Person person = new Person(sheetId, name.trim(), grade);
        person.setTerms(terms);
        person = saved(person);
        audit("PERSON_ADDED", person, user, today(sheetId), terms == null ? "" : " terms=" + terms);
        rollup.recordChanges(sheetId, user, before);
        return person;
    }

    @Transactional
    /** Change a person's name, and record the grade from a date (the sheet's today when none is given),
     *  keeping the grades already recorded; a save leaving the grade as it is on the sheet's today, with no
     *  from-date, records nothing. Their own terms are set to those given (none clears them). */
    public Person update(String sheetId, String user, long personId, long version, String name, String grade,
            LocalDate gradeFrom, Integer terms) {
        Person person = people.findByIdAndSheetId(personId, sheetId).orElseThrow(PersonNotFoundException::new);
        if (person.getVersion() != version) {
            throw new PersonVersionConflictException(person);
        }
        requireFreeName(sheetId, name.trim(), person.getId());
        Rollup.Snapshot before = rollup.take(sheetId);
        LocalDate today = today(sheetId);
        person.setName(name.trim());
        boolean termsChanged = !Objects.equals(terms, person.getTerms());
        person.setTerms(terms);
        if (gradeFrom != null || !grade.equals(person.gradeOn(today))) {
            person.setGrade(grade, gradeFrom != null ? gradeFrom : today);
        }
        Person updated = saved(person);
        audit("PERSON_EDITED", updated, user, today, termsChanged ? " terms=" + (terms == null ? "" : terms) : "");
        rollup.recordChanges(sheetId, user, before);
        return updated;
    }

    /** Retire a person from a date, the sheet's today when none is given. */
    @Transactional
    public Person retire(String sheetId, String user, long personId, LocalDate from) {
        Person person = people.findByIdAndSheetId(personId, sheetId).orElseThrow(PersonNotFoundException::new);
        LocalDate on = from != null ? from : today(sheetId);
        person.setRetiredFrom(on);
        Person retired = saved(person);
        audit.recordOnCommit("PERSON_RETIRED sheet=" + sheetId + " by=" + user + " name=" + retired.getName()
                + " from=" + on);
        return retired;
    }

    /** Put a person on hold from a date (the sheet's today when none is given) to a date when one is
     *  given; a hold ending before it starts is refused. */
    @Transactional
    public Person hold(String sheetId, String user, long personId, LocalDate from, LocalDate to) {
        Person person = people.findByIdAndSheetId(personId, sheetId).orElseThrow(PersonNotFoundException::new);
        LocalDate on = from != null ? from : today(sheetId);
        if (to != null && to.isBefore(on)) {
            throw new HoldRefusedException("A hold cannot end before it starts.");
        }
        Rollup.Snapshot before = rollup.take(sheetId);
        person.hold(on, to);
        Person held = saved(person);
        audit.recordOnCommit("PERSON_HELD sheet=" + sheetId + " by=" + user + " name=" + held.getName()
                + " from=" + on);
        rollup.recordChanges(sheetId, user, before);
        return held;
    }

    /** The grade recorded is the one in force on the sheet's today; extra ends the line. */
    private void audit(String event, Person person, String user, LocalDate today, String extra) {
        audit.recordOnCommit(event + " sheet=" + person.getSheetId() + " by=" + user
                + " name=" + person.getName() + " grade=" + person.gradeOn(today) + extra);
    }

    /** The sheet's today, the date the grade the screen shows is in force on. */
    @Transactional(readOnly = true)
    public LocalDate today(String sheetId) {
        return sheets.findById(sheetId).orElseThrow(SheetNotFoundException::new).getToday();
    }

    private void requireFreeName(String sheetId, String name, Long exceptId) {
        if (people.nameTaken(sheetId, name, exceptId)) {
            throw new PersonNameTakenException();
        }
    }

    /** Save now, so a name another user took at the same moment is refused here, not at commit. */
    private Person saved(Person person) {
        try {
            return people.saveAndFlush(person);
        } catch (DataIntegrityViolationException e) {
            throw new PersonNameTakenException();
        }
    }

    /** The person as stored now, for an editor whose save was refused. */
    @Transactional(readOnly = true)
    public Person current(String sheetId, long personId) {
        return people.findByIdAndSheetId(personId, sheetId).orElseThrow(PersonNotFoundException::new);
    }

    private void requireSheet(String sheetId) {
        if (!sheets.existsById(sheetId)) {
            throw new SheetNotFoundException();
        }
    }
}
package net.officefloor.hq.app.person;

import jakarta.servlet.http.HttpServletRequest;
import jakarta.validation.Valid;
import jakarta.validation.constraints.Min;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Pattern;
import jakarta.validation.constraints.Size;
import java.time.LocalDate;
import java.util.List;
import java.util.Map;
import java.util.Set;
import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;
import org.springframework.orm.ObjectOptimisticLockingFailureException;
import org.springframework.validation.annotation.Validated;
import org.springframework.web.bind.annotation.ExceptionHandler;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.PutMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestHeader;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.ResponseStatus;
import org.springframework.web.bind.annotation.RestController;

/** The people on a sheet. The signed-in user's name comes in the X-User header. */
@RestController
@Validated
@RequestMapping("/api/sheets/{sheetId}/people")
public class PersonController {

    /** A person as the screen shows it, with how many statements were taken of them and the last one's
     *  due-total (n/a when it was) and date; none of either before their first statement; and the ids
     *  of their patrons. Their grade is the one in force on the sheet's today; grades lists every grade
     *  they were given, each with its from-date (YYYY-MM-DD, none for the first); watched says whether
     *  the signed-in user watches them. */
    public record PersonView(long id, String name, String grade, List<GradeView> grades, long version, int statementCount,
            String statedTotal, String statementDate, boolean retired, String retiredFrom,
            boolean held, List<HoldView> holds, List<Long> patronIds, boolean watched, Integer terms) {

        public static PersonView of(Person person, LocalDate today, List<Statement> statements, List<Long> patronIds,
                boolean watched) {
            Statement last = statements.isEmpty() ? null : statements.get(statements.size() - 1);
            return new PersonView(person.getId(), person.getName(), person.gradeOn(today),
                    person.getGrades().stream().map(GradeView::of).toList(), person.getVersion(),
                    statements.size(),
                    last == null ? null : last.getDueTotal() == null ? "n/a" : last.getDueTotal().toPlainString(),
                    last == null ? null : last.getTakenOn().toString(),
                    person.isRetired(), person.getRetiredFrom() == null ? null : person.getRetiredFrom().toString(),
                    person.isHeld(), person.getHolds().stream().map(HoldView::of).toList(), patronIds,
                    watched, person.getTerms());
        }
    }

    /** A grade a person was given and the date it applies from; none for the beginning of time. */
    public record GradeView(String grade, String from) {

        static GradeView of(PersonGrade grade) {
            return new GradeView(grade.getGrade(), grade.getFromDate() == null ? null : grade.getFromDate().toString());
        }
    }

    /** A hold on a person: its from-date (none for the beginning of time) and its to-date (none while it
     *  has no end), each YYYY-MM-DD. */
    public record HoldView(String from, String to) {

        static HoldView of(PersonHold hold) {
            return new HoldView(hold.getFromDate() == null ? null : hold.getFromDate().toString(),
                    hold.getToDate() == null ? null : hold.getToDate().toString());
        }
    }

    /** The dates a hold covers: from a date (none takes the sheet's today) to a date (none: no end). */
    public record HoldRequest(LocalDate from, LocalDate to) {
    }

    public record PersonRequest(
            @NotBlank @Size(max = 200) String name,
            @NotNull @Pattern(regexp = "[ABC]") String grade,
            @Min(0) Integer terms) {
    }

    /** A person's new name and grade, the date the grade applies from (none: the sheet's today, or
     *  nothing recorded when the grade is the one in force then), with the version of the person the
     *  editor loaded. */
    public record PersonUpdate(
            @NotBlank @Size(max = 200) String name,
            @NotNull @Pattern(regexp = "[ABC]") String grade,
            LocalDate gradeFrom,
            @Min(0) Integer terms,
            @NotNull Long version) {
    }

    /** The person to name as a patron. */
    public record PatronRequest(@NotNull Long patronId) {
    }

    /** Whether the signed-in user is to watch the person. */
    public record WatchRequest(@NotNull Boolean watched) {
    }

    /** The date a person is retired from; none takes the sheet's today. */
    public record RetireRequest(LocalDate from) {
    }

    private final PersonService service;

    public PersonController(PersonService service) {
        this.service = service;
    }

    /** The sheet's people in the order they were added. */
    @GetMapping
    public List<PersonView> list(@PathVariable @NotBlank @Size(max = 200) String sheetId,
            @RequestHeader("X-User") @NotBlank @Size(max = 200) String user) {
        Map<Long, List<Statement>> statements = service.statements(sheetId.trim());
        Map<Long, List<Long>> patrons = service.patrons(sheetId.trim());
        List<Person> people = service.list(sheetId.trim());
        LocalDate today = service.today(sheetId.trim());
        Set<Long> watched = service.watchedBy(sheetId.trim(), user.trim());
        return people.stream()
                .map(p -> PersonView.of(p, today, statements.getOrDefault(p.getId(), List.of()),
                        patrons.getOrDefault(p.getId(), List.of()), watched.contains(p.getId())))
                .toList();
    }

    /** Add a person to the sheet. */
    @PostMapping
    public PersonView add(@PathVariable @NotBlank @Size(max = 200) String sheetId,
            @RequestHeader("X-User") @NotBlank @Size(max = 200) String user,
            @RequestBody @Valid PersonRequest request) {
        Person added = service.add(sheetId.trim(), user.trim(), request.name(), request.grade(), request.terms());
        return PersonView.of(added, service.today(sheetId.trim()), List.of(), List.of(), false);
    }

    /** Change a person's name, and give them a grade from a date. */
    @PutMapping("/{personId}")
    public PersonView update(@PathVariable @NotBlank @Size(max = 200) String sheetId,
            @PathVariable long personId,
            @RequestHeader("X-User") @NotBlank @Size(max = 200) String user,
            @RequestBody @Valid PersonUpdate request) {
        try {
            Person updated = service.update(sheetId.trim(), user.trim(), personId, request.version(),
                    request.name(), request.grade(), request.gradeFrom(), request.terms());
            return view(updated, user.trim());
        } catch (ObjectOptimisticLockingFailureException e) {
            // saved by someone else between the version check and the write
            throw new PersonVersionConflictException(service.current(sheetId.trim(), personId));
        }
    }

    /** Retire a person from a date. */
    @PostMapping("/{personId}/retire")
    public PersonView retire(@PathVariable @NotBlank @Size(max = 200) String sheetId,
            @PathVariable long personId,
            @RequestHeader("X-User") @NotBlank @Size(max = 200) String user,
            @RequestBody RetireRequest request) {
        Person retired = service.retire(sheetId.trim(), user.trim(), personId, request.from());
        return view(retired, user.trim());
    }

    /** Put a person on hold from a date, to a date when one is given. */
    @PostMapping("/{personId}/holds")
    public PersonView hold(@PathVariable @NotBlank @Size(max = 200) String sheetId,
            @PathVariable long personId,
            @RequestHeader("X-User") @NotBlank @Size(max = 200) String user,
            @RequestBody HoldRequest request) {
        Person held = service.hold(sheetId.trim(), user.trim(), personId, request.from(), request.to());
        return view(held, user.trim());
    }

    /** A hold that cannot be put on is refused with the reason, for the screen to show. */
    @ExceptionHandler(HoldRefusedException.class)
    @ResponseStatus(HttpStatus.UNPROCESSABLE_ENTITY)
    public Map<String, String> holdRefused(HoldRefusedException e) {
        return Map.of("message", e.getMessage());
    }

    /** Name another person on the sheet as the person's patron. */
    @PostMapping("/{personId}/patrons")
    public PersonView addPatron(@PathVariable @NotBlank @Size(max = 200) String sheetId,
            @PathVariable long personId,
            @RequestHeader("X-User") @NotBlank @Size(max = 200) String user,
            @RequestBody @Valid PatronRequest request) {
        return view(service.addPatron(sheetId.trim(), user.trim(), personId, request.patronId()), user.trim());
    }

    /** Start or stop watching a person as the signed-in user. */
    @PutMapping("/{personId}/watch")
    public PersonView watch(@PathVariable @NotBlank @Size(max = 200) String sheetId,
            @PathVariable long personId,
            @RequestHeader("X-User") @NotBlank @Size(max = 200) String user,
            @RequestBody @Valid WatchRequest request) {
        return view(service.watch(sheetId.trim(), user.trim(), personId, request.watched()), user.trim());
    }

    /** A watch that cannot be started is refused with the reason, for the screen to show. */
    @ExceptionHandler(WatchRefusedException.class)
    @ResponseStatus(HttpStatus.CONFLICT)
    public Map<String, String> watchRefused(WatchRefusedException e) {
        return Map.of("message", e.getMessage());
    }

    /** A patron the person cannot name is refused with the reason, for the screen to show. */
    @ExceptionHandler(PatronRefusedException.class)
    @ResponseStatus(HttpStatus.CONFLICT)
    public Map<String, String> patronRefused(PatronRefusedException e) {
        return Map.of("message", e.getMessage());
    }

    private PersonView view(Person person, String user) {
        return PersonView.of(person, service.today(person.getSheetId()), service.statementsOf(person.getId()),
                service.patronsOf(person.getId()), service.watching(person.getId(), user));
    }

    /** A save from an editor that loaded an older version: refused, answering the person as it is now. */
    @ExceptionHandler(PersonVersionConflictException.class)
    public ResponseEntity<PersonView> conflict(PersonVersionConflictException e, HttpServletRequest request) {
        return ResponseEntity.status(HttpStatus.PRECONDITION_FAILED).body(view(e.getCurrent(), request.getHeader("X-User").trim()));
    }
}
